function getContrast(hex: string): string {
  const clean = hex.replace('#', '');
  const num = parseInt(clean, 16);
  if (isNaN(num)) return '#ffffff';
  const r = (num >> 16) & 255;
  const g = (num >> 8) & 255;
  const b = num & 255;
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return lum > 0.5 ? '#0f172a' : '#ffffff';
}

export function figmaComboToThemePreset(combo: FigmaCombination): ThemePreset {
  const p = combo.palette.filter(c => !["#fcfcfc", "#ffffff"].includes(c.toLowerCase()));
  const colors = p.length >= 3 ? p : [...combo.palette, "#3b82f6", "#6366f1"];
  
  // Pick primary, secondary, accent
  const primary = colors[0] || "#3b82f6";
  const secondary = colors[1] || colors[0];
  const accent = colors[2] || colors[1] || colors[0];
  
  const isTranquilOrDark = combo.category === "Tranquil" || combo.desc.toLowerCase().includes("dark mode") || combo.desc.toLowerCase().includes("low-light");

  // Determine styleCategory
  let styleCategory: ThemeStyle = "minimalistisk";
  let category: "dark" | "light" | "vibrant" | "minimal" | "tech" | "editorial" | "cyberpunk" = "minimal";
  
  switch (combo.category) {
    case "Romantic":
      styleCategory = "mjuk";
      category = "light";
      break;
    case "Playful":
      styleCategory = "djärv";
      category = "vibrant";
      break;
    case "Vibrant":
      styleCategory = "djärv";
      category = "vibrant";
      break;
    case "Neutral":
      styleCategory = "professionell";
      category = "tech";
      break;
    case "Tranquil":
      styleCategory = "mellanläge";
      category = "editorial";
      break;
    case "Seasonal":
      styleCategory = "retro";
      category = "editorial";
      break;
    default:
      styleCategory = "minimalistisk";
      category = "minimal";
  }

  const bg = isTranquilOrDark ? "#171a23" : "#f8fafc";
  const surface = isTranquilOrDark ? "#222634" : "#ffffff";
  const border = isTranquilOrDark ? "#33394a" : "#e2e8f0";
  const text = isTranquilOrDark ? "#f1f5f9" : "#0f172a";
  const textMuted = isTranquilOrDark ? "#94a3b8" : "#64748b";

  return {
    id: "figma-" + combo.num,
    name: "Figma #" + combo.num + ": " + combo.name,
    mood: combo.desc,
    styleCategory,
    category,
    description: `Figma [${combo.category}] - ${combo.desc.slice(0, 110)}...`,
    tokens: {
      primary,
      primaryForeground: getContrast(primary),
      secondary,
      secondaryForeground: getContrast(secondary),
      accent,
      accentForeground: getContrast(accent),
      background: bg,
      surface,
      surfaceForeground: text,
      surfaceBorder: border,
      text,
      textMuted,
      ring: primary,
      glow: accent,
      radius: 8,
      borderWidth: 1,
      shadowMode: combo.category === "Vibrant" ? "glow" : "subtle"
    }
  };
}

export const FIGMA_THEME_PRESETS: ThemePreset[] = FIGMA_COMBINATIONS.map(figmaComboToThemePreset);

